        if not occupied:
            return []
        return [c for c in range(min(occupied), max(occupied) + 1)
                if grid[r][c] != 8]

    def paint(r, c):
        if 0 <= r < h and 0 <= c < w and grid[r][c] == 0:
            out[r][c] = 2

    def paint_row(r, lo=0, hi=None):
        if hi is None:
            hi = w - 1
        for c in range(max(0, lo), min(w - 1, hi) + 1):
            paint(r, c)

    holes = [openings(r) for r in bars]
    if not bars:
        return out

    # Connect the marker to the openings of the first barrier.
    if holes[0]:
        lo, hi = min([mc] + holes[0]), max([mc] + holes[0])
        paint_row(bars[0] - 1, lo, hi)
        for c in holes[0]:
            paint(bars[0], c)

    for i, r in enumerate(bars):
        current = holes[i]
        for c in current:
            paint(r, c)

        if i + 1 < len(bars):
            nxt = holes[i + 1]
            connector = bars[i + 1] - 1

            # Continue each current opening downward until the connector.
            for rr in range(r + 1, connector):
                for c in current:
                    paint(rr, c)

            if len(current) != len(nxt):
                paint_row(connector)
            elif current and nxt:
                paint_row(connector, min(current + nxt), max(current + nxt))
        else:
            for rr in range(r + 1, h):
                for c in current:
                    paint(rr, c)

